    document.querySelectorAll(".om-card[data-entity-open]").forEach(function(card){if(card.dataset.rmCardReady)return;card.dataset.rmCardReady="1";var actions=card.querySelector(".om-card-actions");if(!actions)return;var auth=Array.from(actions.querySelectorAll("button")).find(function(b){return b.textContent.trim()==="授权"});if(auth)auth.dataset.entityAuth="1";var more=Array.from(actions.querySelectorAll("button")).find(function(b){return b.textContent.indexOf("更多")>-1});if(more){var v=document.createElement("button");v.className="om-action";v.textContent="版本";v.dataset.entityVersion="1";actions.insertBefore(v,more)}});
