    if(t.hasAttribute("data-agent-edit")){agentNavigate("configure","react",t.dataset.agentId||"",false);return}
    if(t.hasAttribute("data-agent-back-list")){agentNavigate("list","","",false);return}
    if(t.hasAttribute("data-agent-back-types")){agentNavigate("list","","",false);return}
    if(t.matches(".agent-select-card[data-agent-type]")){var stage=t.closest(".agent-select-page");stage.querySelectorAll(".agent-select-card").forEach(function(b){b.classList.toggle("active",b===t)});var next=stage.querySelector("[data-agent-next]"),label=stage.querySelector("[data-agent-selected-label]");if(next)next.dataset.agentSelected=t.dataset.agentType;if(label)label.textContent=agentType(t.dataset.agentType).name;return}
    if(t.hasAttribute("data-agent-next")){var activeType=t.dataset.agentSelected||"react",currentSelect=new URLSearchParams(location.search);agentNavigate("configure",activeType,currentSelect.get("agent")||"",true);return}
    if(t.dataset.agentTraceTab){selectAgentTrace(t.dataset.agentTraceTab);return}
    if(t.hasAttribute("data-agent-chat-execution-toggle")){var execution=t.closest("[data-agent-chat-execution]"),collapsed=execution&&execution.classList.toggle("collapsed"),arrow=t.querySelector("em");if(arrow)arrow.textContent=collapsed?"⌄":"⌃";return}
